#include <iostream>
#include <string>
#include <set>
int main() {
    std::set<std::string> uniqueStrings;
    std::string input;
    while (std::cin >> input) {
        uniqueStrings.insert(input);
    }
    for (const auto& str : uniqueStrings) {
        std::cout << str << std::endl;
    }
    return 0;
}
